use super::*;
use super::Register as R;
use super::TimerUnit;

fn advance(timer: &mut TimerUnit, cycles: usize) -> usize {
    (0..cycles)
        .filter(|_| timer.tick_tcycle())
        .count()
}

fn fast_timer() -> TimerUnit {
    let mut timer = TimerUnit::new(Model::Dmg);
    timer.write(R::Tac, 0b101);
    timer
}

#[test]
fn div_exposes_the_upper_byte() {
    let mut timer = TimerUnit::new(Model::Dmg);

    advance(&mut timer, 255);
    assert_eq!(timer.read(R::Div), 0);

    advance(&mut timer, 1);
    assert_eq!(timer.read(R::Div), 1);
}

#[test]
fn selected_clock_controls_the_increment_period() {
    for (selection, period) in [
        (0b00, 1024),
        (0b01, 16),
        (0b10, 64),
        (0b11, 256),
    ] {
        let mut timer = TimerUnit::new(Model::Dmg);
        timer.write(R::Tac, 0b100 | selection);

        advance(&mut timer, period - 1);
        assert_eq!(timer.read(R::Tima), 0);

        advance(&mut timer, 1);
        assert_eq!(timer.read(R::Tima), 1);
    }
}

#[test]
fn resetting_div_can_increment_tima() {
    let mut timer = fast_timer();

    advance(&mut timer, 8);
    timer.write(R::Div, 0xFF);

    assert_eq!(timer.internal_divider(), 0);
    assert_eq!(timer.read(R::Tima), 1);
}

#[test]
fn overflow_reloads_after_four_tcycles() {
    let mut timer = fast_timer();
    timer.write(R::Tima, 0xFF);
    timer.write(R::Tma, 0x42);

    assert_eq!(advance(&mut timer, 16), 0);
    assert_eq!(timer.read(R::Tima), 0);

    assert_eq!(advance(&mut timer, 3), 0);
    assert_eq!(timer.read(R::Tima), 0);

    assert!(timer.tick_tcycle());
    assert_eq!(timer.read(R::Tima), 0x42);
}

#[test]
fn tima_write_cancels_pending_reload() {
    let mut timer = fast_timer();
    timer.write(R::Tima, 0xFF);

    advance(&mut timer, 16);
    timer.write(R::Tima, 0x77);

    assert_eq!(advance(&mut timer, 4), 0);
    assert_eq!(timer.read(R::Tima), 0x77);
}

#[test]
fn writes_during_active_reload_follow_the_chosen_model() {
    let mut timer = fast_timer();
    timer.write(R::Tima, 0xFF);
    timer.write(R::Tma, 0x42);

    assert_eq!(advance(&mut timer, 20), 1);

    timer.write(R::Tima, 0x99);
    assert_eq!(timer.read(R::Tima), 0x42);

    timer.write(R::Tma, 0x66);
    assert_eq!(timer.read(R::Tima), 0x66);

    advance(&mut timer, 4);
    timer.write(R::Tima, 0x99);
    assert_eq!(timer.read(R::Tima), 0x99);
}
